// Public GitHub reads only; no token, repository write, or private data access.
const ROOT='https://api.github.com';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function get(path,signal){const r=await fetch(ROOT+path,{signal,headers:{Accept:'application/vnd.github+json'}});if(!r.ok)throw new Error(r.status===403||r.status===429?'GitHub’s public request limit was reached. Try later.':r.status===404?'The public GitHub profile could not be found.':'GitHub could not be reached ('+r.status+').');return r.json();}
export async function loadGithub(){const area=document.querySelector('#githubResults');if(!area)return;const button=document.querySelector('[data-action="github-refresh"]');if(button)button.disabled=true;area.textContent='Loading public repositories and commits…';const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const repos=await get('/users/yashjoshi1827/repos?sort=pushed&per_page=6',controller.signal);if(!Array.isArray(repos))throw new Error('Unexpected GitHub response.');const chosen=repos.filter(r=>!r.fork).slice(0,3);const rows=await Promise.all(chosen.map(async repo=>{try{const commits=await get('/repos/yashjoshi1827/'+encodeURIComponent(repo.name)+'/commits?per_page=3',controller.signal);return {repo,commits:Array.isArray(commits)?commits:[]};}catch{return {repo,commits:[]};}}));if(!area.isConnected)return;area.innerHTML=rows.length?rows.map(({repo,commits})=>`<div class="github-record"><span class="commit-dot"></span><div><strong><a href="https://github.com/yashjoshi1827/${encodeURIComponent(repo.name)}" target="_blank" rel="noopener noreferrer">${escape(repo.name)} ↗</a></strong><p>${escape(repo.description||'Public repository')}</p>${commits.map(c=>{const sha=String(c.sha||'');if(!/^[a-f0-9]{40}$/.test(sha))return '';return `<p><a href="https://github.com/yashjoshi1827/${encodeURIComponent(repo.name)}/commit/${sha}" target="_blank" rel="noopener noreferrer"><code>${sha.slice(0,7)}</code> ${escape(String(c.commit?.message||'').split('\n')[0])}</a></p>`;}).join('')}${!commits.length?'<p>Commit details unavailable for this repository.</p>':''}</div></div>`).join(''):'No public non-fork repositories were returned.';const status=document.createElement('p');status.className='github-status';status.textContent='Fetched '+new Date().toLocaleString('en-IN')+' · Latest commits from up to 3 recently pushed public repositories; not a complete history.';area.append(status);}catch(e){area.textContent=e.name==='AbortError'?'GitHub request timed out. Try again when connected.':e.message;}finally{clearTimeout(timer);if(button?.isConnected)button.disabled=false;}}
